// src/pages/BookRegistration.js

import React, { useState } from 'react';
import '../estilos/BookRegistration.css';

// 💡 IMPORTACIÓN CRÍTICA: Necesaria para la comunicación con el backend
import { useBookManagement } from '../hooks/useBookManagement'; 

const BookRegistration = () => {
  
  // 1. Uso del Custom Hook para la API
  const { 
    registerBook, 
    isLoading, 
    error, 
    successMessage, 
    setError, 
    setSuccessMessage 
  } = useBookManagement();

  // 2. Estado del Formulario con el campo 'ejemplares' incluido
  const [formData, setFormData] = useState({
    titulo: '',
    autor: '',
    categoria: '',
    año: '',
    tipo: 'fisico', // Valor por defecto
    ejemplares: '1' // Valor por defecto
  });

  const [pdfFiles, setPdfFiles] = useState([]);
  const [coverImage, setCoverImage] = useState(null);
  const [errors, setErrors] = useState({});

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // Limpieza de estados y errores
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: '' }));
    setError(null); 
    setSuccessMessage(null); 
  };

  const handlePdfFilesChange = (e) => {
    const files = Array.from(e.target.files);
    
    if (files.length + pdfFiles.length > 5) {
      alert('Máximo 5 archivos PDF permitidos');
      return;
    }

    setPdfFiles(prev => [...prev, ...files]);
  };

  const handleCoverImageChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setCoverImage(file);
  };

  const removePdfFile = (index) => {
    setPdfFiles(prev => prev.filter((_, i) => i !== index));
  };

  const removeCoverImage = () => {
    setCoverImage(null);
  };

  const validateForm = () => {
    const newErrors = {};

    // Validaciones básicas de campos de texto
    if (!formData.titulo.trim()) newErrors.titulo = 'El título es obligatorio';
    if (!formData.autor.trim()) newErrors.autor = 'El autor es obligatorio';
    if (!formData.categoria.trim()) newErrors.categoria = 'La categoría es obligatoria';
    
    // Validación de Año
    const currentYear = new Date().getFullYear();
    const year = parseInt(formData.año);
    if (!formData.año.trim() || isNaN(year) || year < 1000 || year > currentYear) {
      newErrors.año = `El año debe ser un número válido (máx. ${currentYear})`;
    }
    
    if (!formData.tipo) newErrors.tipo = 'El tipo es obligatorio';

    // Validación de Ejemplares (solo si es físico)
    const ejemplares = parseInt(formData.ejemplares);
    if (formData.tipo === 'fisico' && (isNaN(ejemplares) || ejemplares < 1)) {
       newErrors.ejemplares = 'Debe haber al menos 1 ejemplar físico.';
    }


    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    // 3. Creación de FormData (CRÍTICO para envío de archivos)
    const submitData = new FormData();
    
    // Campos de texto y corrección de 'ejemplares' si es digital
    Object.keys(formData).forEach(key => {
      if (key === 'ejemplares' && formData.tipo === 'digital') {
        submitData.append(key, 0); 
      } else {
        submitData.append(key, formData[key]);
      }
    });
    
    // Archivos PDF y Imagen de portada
    pdfFiles.forEach(file => { submitData.append('pdfFiles', file); });
    if (coverImage) { submitData.append('coverImage', coverImage); }
    
    // 4. Llamada al Hook que hace la petición a la API
    const result = await registerBook(submitData);

    if (result.success) {
      // Limpiar formulario al tener éxito
      setFormData({
        titulo: '',
        autor: '',
        categoria: '',
        año: '',
        tipo: 'fisico',
        ejemplares: '1'
      });
      setPdfFiles([]);
      setCoverImage(null);
    } 
  };

  return (
    <div className="book-registration">
      <div className="registration-container">
        <h1>Registro de Libros</h1>
        
        {/* Mostrar mensajes de estado */}
        {error && <div className="message-box error">❌ Error: {error}</div>}
        {successMessage && <div className="message-box success">✅ {successMessage}</div>}
        
        <form onSubmit={handleSubmit} className="registration-form">
          <div className="form-section">
            <h2>Información Básica</h2>
            
            <div className="form-group">
              <label htmlFor="titulo">Título *</label>
              <input
                type="text" id="titulo" name="titulo" value={formData.titulo}
                onChange={handleInputChange} className={errors.titulo ? 'error' : ''}
                placeholder="Ingrese el título del libro"
              />
              {errors.titulo && <span className="error-message">{errors.titulo}</span>}
            </div>

            <div className="form-group">
              <label htmlFor="autor">Autor *</label>
              <input
                type="text" id="autor" name="autor" value={formData.autor}
                onChange={handleInputChange} className={errors.autor ? 'error' : ''}
                placeholder="Ingrese el nombre del autor"
              />
              {errors.autor && <span className="error-message">{errors.autor}</span>}
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="categoria">Categoría *</label>
                <input
                  type="text" id="categoria" name="categoria" value={formData.categoria}
                  onChange={handleInputChange} className={errors.categoria ? 'error' : ''}
                  placeholder="Ej: Ciencia Ficción, Historia, etc."
                />
                {errors.categoria && <span className="error-message">{errors.categoria}</span>}
              </div>

              <div className="form-group">
                <label htmlFor="año">Año de Publicación *</label>
                <input
                  type="number" id="año" name="año" value={formData.año}
                  onChange={handleInputChange} className={errors.año ? 'error' : ''}
                  placeholder="Ej: 2024"
                />
                {errors.año && <span className="error-message">{errors.año}</span>}
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Tipo *</label>
                <div className="radio-group">
                  <label className="radio-option">
                    <input type="radio" name="tipo" value="fisico" checked={formData.tipo === 'fisico'} onChange={handleInputChange}/>
                    <span>Físico</span>
                  </label>
                  <label className="radio-option">
                    <input type="radio" name="tipo" value="digital" checked={formData.tipo === 'digital'} onChange={handleInputChange}/>
                    <span>Digital</span>
                  </label>
                </div>
                {errors.tipo && <span className="error-message">{errors.tipo}</span>}
              </div>

              {/* CAMPO EJEMPLARES */}
              <div className="form-group">
                <label htmlFor="ejemplares">Ejemplares Físicos *</label>
                <input
                  type="number" id="ejemplares" name="ejemplares" min="0" value={formData.ejemplares}
                  onChange={handleInputChange} className={errors.ejemplares ? 'error' : ''}
                  placeholder="Cantidad"
                  disabled={formData.tipo === 'digital'} // Deshabilitar si es Digital
                />
                {errors.ejemplares && <span className="error-message">{errors.ejemplares}</span>}
              </div>
            </div>
          </div>

          <div className="form-section">
            <h2>Archivos PDF (Máx. 5 archivos)</h2>
            <div className="form-group">
              <input type="file" id="pdfFiles" multiple accept=".pdf" onChange={handlePdfFilesChange} className="file-input"/>
              <label htmlFor="pdfFiles" className="file-label">Seleccionar archivos PDF</label>
              {pdfFiles.length > 0 && (
                <div className="file-list">
                  <h4>Archivos seleccionados:</h4>
                  {pdfFiles.map((file, index) => (
                    <div key={index} className="file-item">
                      <span>{file.name}</span>
                      <button type="button" onClick={() => removePdfFile(index)} className="remove-btn">×</button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="form-section">
            <h2>Imagen de Portada</h2>
            <div className="form-group">
              <input type="file" id="coverImage" accept=".png,.jpg,.jpeg,.webp" onChange={handleCoverImageChange} className="file-input"/>
              <label htmlFor="coverImage" className="file-label">Seleccionar imagen de portada</label>
              {coverImage && (
                <div className="cover-preview">
                  <h4>Vista previa:</h4>
                  <div className="image-preview">
                    <img src={URL.createObjectURL(coverImage)} alt="Vista previa" />
                    <button type="button" onClick={removeCoverImage} className="remove-btn">×</button>
                  </div>
                </div>
              )}
            </div>
          </div>

          <button type="submit" className="submit-btn" disabled={isLoading}>
            {isLoading ? 'Registrando...' : 'Registrar Libro'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default BookRegistration;
